{
  "name": "bugxhunter",
  "version": "0.9.5",
  "description": "BugXHunter: an AI security-testing agent with a sandboxed runner, a passkey-sealed key vault and read-only GitHub access. `npx bugxhunter` runs it on your machine.",
  "license": "MIT",
  "homepage": "https://bugxhunter.com",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cintelis/bugxhunter-runner.git"
  },
  "bugs": {
    "url": "https://github.com/cintelis/bugxhunter-runner/issues"
  },
  "keywords": [
    "security",
    "pentest",
    "bug-bounty",
    "ai-agent",
    "opencode",
    "vulnerability-scanner",
    "code-review"
  ],
  "type": "module",
  "bin": {
    "bugxhunter": "bin/bugxhunter.mjs"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "^1.3.0",
    "@opencode-ai/sdk": "^1.17.11",
    "dotenv": "^18.0.6",
    "express": "^5.2.1",
    "express-rate-limit": "^8.7.1",
    "opencode-ai": "^1.18.35"
  },
  "publishConfig": {
    "access": "public"
  }
}
